-- American spelling for the comment bank: updates the rows the seed cannot (the seed never overwrites).
-- Safe to re-run.
UPDATE comment_phrases SET text = $q${name} is learning to retell a story in order rather than listing favorite parts.$q$, updated_at = now() WHERE seed_key = $q$reading-020$q$;
UPDATE comment_phrases SET text = $q${name} reads accurately but with little expression. Reading a favorite page as if telling the story would help.$q$, updated_at = now() WHERE seed_key = $q$reading-034$q$;
UPDATE comment_phrases SET text = $q${name} relies on words {he} has memorized and finds new words hard. The next step is to sound out every new word rather than guess.$q$, updated_at = now() WHERE seed_key = $q$phonics-020$q$;
UPDATE comment_phrases SET text = $q${name}'s organization has improved since the October progress report; {his} paragraphs now follow a clear order.$q$, updated_at = now() WHERE seed_key = $q$writing-032$q$;
UPDATE comment_phrases SET text = $q$On {his} last piece {name} scored ____ out of 4 for ideas and ____ for organization. The ideas are there, and order is the next step.$q$, updated_at = now() WHERE seed_key = $q$writing-033$q$;
UPDATE comment_phrases SET text = $q${name} sometimes speaks unkindly to classmates when frustrated. We are practicing stopping and using a calm sentence, and the same at home would help.$q$, updated_at = now() WHERE seed_key = $q$behavior-025$q$;
UPDATE comment_phrases SET text = $q${name} is learning to read a short book alone and say what happened.$q$, home1 = $q$Read ten minutes each evening and tell someone one thing that happened.$q$, home2 = $q$Reread a favorite book and read one page with expression.$q$, updated_at = now() WHERE seed_key = $q$ladder-003$q$;
UPDATE comment_phrases SET text = $q${name} is learning the sound of each letter.$q$, home1 = $q$Practice five letter sounds a day with cards. Say the sound, not the name.$q$, home2 = $q$Find things at home that start with the sound of the day.$q$, updated_at = now() WHERE seed_key = $q$ladder-007$q$;
UPDATE comment_phrases SET text = $q${name} is learning to split two-syllable words into parts.$q$, home1 = $q$Clap the parts of long words in a book and read each part.$q$, home2 = $q$Spell the week's long words by writing each part in a different color.$q$, updated_at = now() WHERE seed_key = $q$ladder-012$q$;
UPDATE comment_phrases SET text = $q${name} is learning to answer with one English word and follow one-step directions.$q$, home1 = $q$Ask simple questions with one-word answers: What color? How many?$q$, home2 = $q$Give one-step instructions in English at home: Open the door.$q$, updated_at = now() WHERE seed_key = $q$ladder-019$q$;
UPDATE comment_phrases SET text = $q${name} is learning to answer in a short full sentence.$q$, home1 = $q$When {he} answers with one word, ask {him} to say it again as a sentence.$q$, home2 = $q$Practice "I like ____" and "I have ____" about things at home.$q$, updated_at = now() WHERE seed_key = $q$ladder-020$q$;
UPDATE comment_phrases SET text = $q${name} is learning to ask for things and for help in English.$q$, home1 = $q$Ask {him} to ask for snacks or help in English, even with mistakes.$q$, home2 = $q$Practice three questions: Can I have, Where is, What is.$q$, updated_at = now() WHERE seed_key = $q$ladder-021$q$;
UPDATE comment_phrases SET text = $q${name} is learning to give a short talk with a beginning, middle and end.$q$, home1 = $q$Practice a one-minute talk about a hobby, then give it to the family.$q$, home2 = $q$Record the talk on a phone and listen for one thing to improve.$q$, updated_at = now() WHERE seed_key = $q$ladder-024$q$;
SELECT count(*) AS british_left FROM comment_phrases WHERE text ~* 'favourite|colour|memorised|organisation|practis(e|ing)' OR home1 ~* 'practis(e|ing)' OR home2 ~* 'practis(e|ing)';
